!function(e){function t(t){for(var n,i,o=t[0],m=t[1],d=t[2],s=0,g=[];s<o.length;s++)i=o[s],Object.prototype.hasOwnProperty.call(a,i)&&a[i]&&g.push(a[i][0]),a[i]=0;for(n in m)Object.prototype.hasOwnProperty.call(m,n)&&(e[n]=m[n]);for(c&&c(t);g.length;)g.shift()();return p.push.apply(p,d||[]),r()}function r(){for(var e,t=0;t<p.length;t++){for(var r,i=p[t],o=!0,m=1;m<i.length;m++)r=i[m],0!==a[r]&&(o=!1);o&&(p.splice(t--,1),e=n(n.s=i[0]))}return e}function n(t){if(i[t])return i[t].exports;var r=i[t]={i:t,l:!1,exports:{}};return e[t].call(r.exports,r,r.exports,n),r.l=!0,r.exports}var i={},a={75:0},p=[];n.m=e,n.c=i,n.d=function(e,t,r){n.o(e,t)||Object.defineProperty(e,t,{enumerable:!0,get:r})},n.r=function(e){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(e,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(e,"__esModule",{value:!0})},n.t=function(e,t){if(1&t&&(e=n(e)),8&t)return e;if(4&t&&"object"==typeof e&&e&&e.__esModule)return e;var r=Object.create(null);if(n.r(r),Object.defineProperty(r,"default",{enumerable:!0,value:e}),2&t&&"string"!=typeof e)for(var i in e)n.d(r,i,function(t){return e[t]}.bind(null,i));return r},n.n=function(e){var t=e&&e.__esModule?function(){return e.default}:function(){return e};return n.d(t,"a",t),t},n.o=function(e,t){return Object.prototype.hasOwnProperty.call(e,t)},n.p="";var o=window.webpackJsonp=window.webpackJsonp||[],m=o.push.bind(o);o.push=t,o=o.slice();for(var d=0;d<o.length;d++)t(o[d]);var c=m;p.push([26,0]),r()}({26:function(e,t,r){"use strict";r.r(t);var n=r(0);Object(n.a)("de","army",r(27),r(1))},27:function(e){e.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"坦克","link":"de_army#de_army_tank"}],"model":"Ⅴ号黑豹坦克","description":"<h6>综述：</h6><p>Ⅴ号（黑豹）坦克属重型坦克，它从1942年11月开始生产，首批生产的型号是D型，随后继续有改进后的A、G型（1944年并已着手研制豹式和豹式Ⅱ型，但因当时战争已进入德本土，生产已呈混乱状态，因此尽管样车已研制出来，但最终也未能量产）。Ⅴ号（黑豹）坦克一共生产了近6000辆，由于其有坚固的前装甲和火力强大的坦克炮，其优越的防护和作战性能受到德军的赞扬（苏军在库尔斯克战役后用缴获的一些豹式坦克进行测试，用一门7.62mm的T-34坦克炮在100m距离外对准豹式坦克的前装甲射击，射出的30发穿甲弹仅有一发能击穿其正面装甲；而豹式坦克的火炮却可以在1200-1500mm距离从正面击毁T-34坦克）。但该车由于太重所产生的机械故障和车侧装甲太薄等问题，故也一度影响了它作战能力的发挥。</p>","part1title":"系列型号","part1description":"","part1content":[{"image":"imgs/de/army/de_army_tankv_11.jpg","description":"<h6>Ⅴ号（黑豹）D型坦克（Sd.Kfz.171 Pz.Kpfw.V Ausf.D Panther）</h6><p>该型车在1942年11月开始生产，至1943年9月 一共生产了860多辆。</p><p>D型车身长8.86m, 车宽3.4m, 车高2.95m, 车重43t；装甲厚度16-100mm；发动机230马力，最大车速46km/h, 最大行程200km; 主要武器为一门75mm KW.K L/70坦克炮，2挺7.92mm MG34机枪，乘员5人。</p><p>初期生产的D型车由于履带、悬挂系统和动力系统都存在一定问题，因此在初期战争中，抛锚率十分高。</p>","caption":"<strong>外形特点：</strong><ol><li>悬挂系统内使用重迭式负重轮。</li><li>车体两侧安装了整块的装甲钢板。</li><li>烟雾发生器安装在炮塔顶部两侧。</li></ol>"},{"image":"imgs/de/army/de_army_tankv_12.jpg","description":"<h6>Ⅴ号（黑豹）A型坦克（Sd.Kfz.171 Pz.Kpfw.V Ausf.A Panther）</h6><p>该型车于1943年8月开始生产，总生产量接近1800辆。</p><p>A型车除车重（44.8t)和正面装甲厚度（110mm)略有增加外，其余都与D型车基本相同。开始的A型坦克都涂有防磁的水泥涂层，以防磁性地雷或磁性手雷的攻击（不过在1944年后期取消了），它针对D型车在战斗中发现的弱点对动力系统进行了改进，提高了它的可靠性；它还加强了武器装备，增加了一挺高射机枪，当受到空中威胁时，可操纵对空机枪实施空中防卫。中后期生产的坦克还将机枪孔改装为新式的球形机枪座。</p>","caption":"<strong>外形特点：</strong><ol><li>取消了炮塔顶部两侧的烟雾发生器，改在炮塔顶部安装一个短管的榴弹发射器，可发射榴弹和烟雾弹。</li><li>车体正面还保留观察窗，但有些坦克的机枪孔已换成球形机枪座。</li></ol>"},{"image":"imgs/de/army/de_army_tankv_13.jpg","description":"<h6>Ⅴ号（黑豹）G型坦克（Sd.Kfz.171 Pz.Kpfw.V Ausf.G Panther）</h6><p>该型车生产于1944年3月至1945年4月，一共生产了3740辆。是二战末期产量最大的坦克。</p><p>G型坦克主要在装甲上进行了加强，它的正面装甲的倾斜度更大，车体两侧的装甲钢板厚度从40mm增加至50mm。炮弹的数量也从79发增加至82发。该型坦克已全部安装了球形机枪座和更先进的瞄准器。</p>","caption":"<strong>外形特点：</strong><ol><li>车体前部的观察孔已取消，用驾驶舱顶部的可旋转潜望镜替代。</li><li>车体前部的机枪座为球形机枪座。</li></ol>"},{"image":"imgs/de/army/de_army_tankv_14.jpg","description":"<h6>Ⅴ号（黑豹）F型坦克（Sd.Kfz.171 Pz.Kpfw.V Ausf. F Panther）</h6><p>这是黑豹系列坦克的最终型号，特点是炮塔更窄，装甲更厚，1945年1月该车正式定型，但在准备量产时，德国已战败投降。</p>","caption":""},{"image":"imgs/de/army/de_army_tankv_15.jpg","description":"<h6>Ⅴ号（黑豹）Ⅱ型坦克（ Pz.Kpfw. Panther Ⅱ）</h6><p>设计思想是要将黑豹坦克升级，在豹Ⅰ动力系统基础上，让部分配件与虎Ⅱ部件通用，并加强装甲与武器火力，但到1945年德国战败时，只完成了2辆原型车，二战结束后此车被运到美国的坦克博物馆里（见图：刚抵达时，此车还可开动，但由于专用的窄型炮塔已损坏，只能用黑豹G型坦克的炮塔替代）。</p>","caption":""},{"image":"imgs/de/army/de_army_tankv_16.jpg","description":"<h6>Ⅴ号豹式指挥坦克（Sd.Kfz.267和268 Bef.Pzwg.Panther）</h6><p>这是在D、A或G型坦克上安装上无线收发器和天线后，作为指挥车使用的坦克。267和268只是所安装的无线收发器有型号不同。</p>","caption":""},{"image":"imgs/de/army/de_army_tankv_17.jpg","description":"<h6>Ⅴ号豹式维修坦克（Sd.Kfz.179  Bergepanzer.Panther）</h6><p>这是为了解决战损的重型坦克的维修和回收问题所生产，它拆除了豹式坦克的炮塔，在车体上安装 了40t的绞盘和1.5t的起重机，并在车后加装了一个大铲；车上有支撑架安放一挺机枪。此型维修坦克从1943年6月开始生产，至1945年3月共生产了350多辆，其中在D型基础上改装12辆，A型基础上改装了232辆，G型基础上改装了107辆。这种维修车在战损坦克的维修和回收中发挥了极大作用，在每个黑豹坦克营中都会配备2辆（但也难以满足战场要求）。</p>","caption":""}],"part2title":"战场上的Ⅴ号（黑豹）坦克","part2description":"<p>1943年7月，在苏联的库尔斯克Ⅴ号（黑豹）坦克首次参加了战斗，但由于初期生产的D型坦克的机械问题，参加战斗测试的200辆黑豹坦克（隶属第10装甲旅）第一天就有100多辆因抛锚退出了战场，9天后只剩下40多辆仍能参加战斗；但后来随着坦克的不断改进，黑豹坦克在东线、意大利、西欧和北欧的战斗中，因其前装甲的坚固和火炮的强大威力，战绩突出，受到德军的赞扬，一直到二战结束，它与虎式坦克一起，成为德军对抗对方重型坦克的主力装备。</p><p>在诺曼第战役中，参战的黑豹A型坦克在反击中对盟军造成很大威胁，美军甚至认为：要有效对抗一辆黑豹坦克，美军必须要投入5辆M坦克进行攻击。在与Ⅳ号坦克协同作战时，黑豹坦克会作装甲编队的侧翼保护用；到了1945年，在意大利防线和柏林战役中，德军还利用黑豹坦克的炮塔修建防御炮台（混凝土工事），用威力强大的坦克炮抗击对方装甲部队的进攻。</p>","part2content":[{"image":"imgs/de/army/de_army_tankv_31.jpg","description":"1943年，在苏联库尔斯克战役中首次亮相的Ⅴ号（黑豹）D型坦克，一位指挥官正在指挥坦克前进。","caption":""},{"image":"imgs/de/army/de_army_tankv_32.jpg","description":"1944年，一辆在东线执行战斗任务的Ⅴ号（黑豹）D型坦克，炮塔侧面装上了履带板附加装甲防护，车体上涂上了防磁层，由于长期在野外执行任务，车身上沾满了泥土，但整车基本保持完好状态。","caption":""},{"image":"imgs/de/army/de_army_tankv_33.jpg","description":"1944年，隶属德国党卫军第五“维京”装甲师第五装甲团第11 营的一辆Ⅴ号（黑豹）A型坦克与步兵一起行进。","caption":""},{"image":"imgs/de/army/de_army_tankv_34.jpg","description":"1944年5月，隶属德国党卫军第一“阿道夫·希特勒警卫旗队”装甲师的一辆Ⅴ号（黑豹）A型坦克，正在比利时城镇街道上行进。","caption":""},{"image":"imgs/de/army/de_army_tankv_35.jpg","description":"1943年在意大利战场上被盟军缴获的一辆Ⅴ号（黑豹）A型坦克，从图上看车体并无大的损伤。","caption":""},{"image":"imgs/de/army/de_army_tankv_36.jpg","description":"德军第4装甲师Ⅴ号（黑豹）G型坦克正在集结。坦克车体很新净，应该是不久前才接收的装备。","caption":""},{"image":"imgs/de/army/de_army_tankv_37.jpg","description":"正在开赴前线的德军“骷髅”师装甲团所属的Ⅴ号（黑豹）G型坦克。旁边还有一辆Sd.Kfz233型装甲车同行。","caption":""},{"image":"imgs/de/army/de_army_tankv_38.jpg","description":"1945年春，在西线战场上一队被盟军击毁的德军Ⅴ号（黑豹）G型坦克，图中右后方还停着一辆美军的坦克，看图上的情况，应该此战场发生过激烈的坦克交战。","caption":""},{"image":"imgs/de/army/de_army_tankv_39.jpg","description":"在意大利防线的一个小山坡上，德军将Ⅴ号（黑豹）A型坦克的炮塔造成一个火炮防御工事，以期发挥其火炮威力强大的优势，抗击盟军的进攻。","caption":""}]}')}});